                if (colTblDuAnRecords != null)
                {
                    foreach (SweetSoft.QLDA.DataAccess.TblDuAn item in colTblDuAnRecords)
                    {
                        if (item.MaHopDongThucHien == null ||item.MaHopDongThucHien != MaHopDongThucHien)
                        {
                            item.MaHopDongThucHien = MaHopDongThucHien;
                        }
                    }
               }
		}
        #endregion
    
        #region Deep Save
		
        public void DeepSave()
        {
            Save();
            
                if (colTblDuAnRecords != null)
                {
                    colTblDuAnRecords.SaveAll();
               }
		}
        #endregion
	}
}
